create table if not exists public.categories(id bigint generated by default as identity primary key,slug text unique not null,name text not null,description text not null default '',cover_image text,parent_id bigint references public.categories(id) on delete set null,sort_order int not null default 0,created_at timestamptz not null default now());create table if not exists public.posts(id bigint generated by default as identity primary key,slug text unique not null,title text not null,excerpt text not null default '',content text not null default '',cover_image text,category_id bigint references public.categories(id) on delete set null,tags text[] not null default '{}',status text not null default 'draft' check(status in ('draft','published')),published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table if not exists public.admins(user_id uuid primary key references auth.users(id) on delete cascade);alter table public.categories enable row level security;alter table public.posts enable row level security;alter table public.admins enable row level security;create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()) $$;create policy "public read categories" on public.categories for select using(true);create policy "admin write categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());create policy "public read published posts" on public.posts for select using(status='published' or public.is_admin());create policy "admin write posts" on public.posts for all using(public.is_admin()) with check(public.is_admin());create policy "admin read self" on public.admins for select using(auth.uid()=user_id);insert into public.categories(slug,name,description,cover_image,sort_order) values ('politics','Politics','Power, policy and the people caught in between.','/img/cat-politics.jpg',1),('science','Science','Curiosity, experiments and the wonder of how things work.','/img/cat-science.jpg',2),('books','Books','Notes and reviews from my reading shelf, in Hindi and English.','/img/cat-books.jpg',3),('cinema','Cinema','Films I loved, films I argued with, genre by genre.','/img/cat-cinema.jpg',4),('philosophy','Philosophy','Big questions, small certainties.','/img/cat-philosophy.jpg',5),('my-questions','My questions','Personal questions I keep coming back to.','/img/cat-my-questions.jpg',6),('entangled-minds','Entangled Minds','Where ideas from different worlds collide.','/img/cat-entangled-minds.jpg',7),('unpolished-beginner','Unpolished Beginner','Learning in public, rough edges included.','/img/cat-unpolished-beginner.jpg',8) on conflict(slug) do nothing;create index if not exists posts_status_idx on public.posts(status,published_at desc);
insert into storage.buckets(id,name,public) values ('blog-images','blog-images',true) on conflict(id) do nothing;
create policy "public read blog images" on storage.objects for select using(bucket_id='blog-images');
create policy "admin upload blog images" on storage.objects for insert to authenticated with check(bucket_id='blog-images' and public.is_admin());
create policy "admin update blog images" on storage.objects for update to authenticated using(bucket_id='blog-images' and public.is_admin()) with check(bucket_id='blog-images' and public.is_admin());
create policy "admin delete blog images" on storage.objects for delete to authenticated using(bucket_id='blog-images' and public.is_admin());
